      "title": "Lesson 25 Grammar Flashcards",
      "cards": [
        {
          "prompt": "ἔλυον",
          "answer": "I was releasing / they were releasing — 1. Building the imperfect active"
        },
        {
          "prompt": "ἔλυες / ἔλυε(ν)",
          "answer": "you were releasing / he or she was releasing — 1. Building the imperfect active"
        },
        {
          "prompt": "ἐλύομεν / ἐλύετε",
          "answer": "we were releasing / you (plural) were releasing — 1. Building the imperfect active"
        },
        {
          "prompt": "ἤκουον",
          "answer": "I was listening / they were listening — 1. Building the imperfect active"
        },
        {
          "prompt": "ἐλυόμην / ἐλύου",
          "answer": "I / you (singular) was/were releasing for myself/yourself — 2. Imperfect middle and deponent verbs"
        },
        {
          "prompt": "ἐλύετο / ἐλυόμεθα",
          "answer": "he was / we were releasing for himself/ourselves — 2. Imperfect middle and deponent verbs"
        },
        {
          "prompt": "ἐλύεσθε / ἐλύοντο",
          "answer": "you (plural) / they were releasing for yourselves/themselves — 2. Imperfect middle and deponent verbs"
        },
        {
          "prompt": "διελέγετο",
          "answer": "he was conversing — 2. Imperfect middle and deponent verbs"
        },
        {
          "prompt": "ἐποίουν / ἐποίει",
          "answer": "I/they was/were making / he or she was making — 3. Contract verbs and εἰμί in the past"
        },
        {
          "prompt": "ἐποιοῦμεν / ἐποιεῖτε",
          "answer": "we were making / you (plural) were making — 3. Contract verbs and εἰμί in the past"
        },
        {
          "prompt": "ἦν / ἦσθα / ἦν",
          "answer": "I was / you were / he or she was — 3. Contract verbs and εἰμί in the past"
        },
        {
          "prompt": "ἦμεν / ἦτε / ἦσαν",
          "answer": "we were / you (plural) were / they were — 3. Contract verbs and εἰμί in the past"
        },
        {
          "prompt": "ὁ ἀνὴρ ἤσθιεν.",
          "answer": "The man was eating. — 4. Choosing a viewpoint: imperfect and aorist"
        },
        {
          "prompt": "ὁ φίλος ἦλθεν.",
