            [
              "σοφός / σοφώτερος / σοφώτατος",
              "wise / wiser / wisest"
            ],
            [
              "πλούσιος / πλουσιώτερος / πλουσιώτατος",
              "wealthy / wealthier / wealthiest"
            ],
            [
              "χαλεπός / χαλεπώτερος / χαλεπώτατος",
              "difficult / more difficult / most difficult"
            ],
            [
              "σοφωτέρα / σοφώτερον",
              "wiser: feminine / neuter singular"
            ]
          ]
