        {
          "prompt": "δηλῶ / δηλοῖς / δηλοῖ",
          "answer": "I / you / he makes clear — 1. Contract verbs in -όω"
        },
        {
          "prompt": "δηλοῦμεν / δηλοῦτε / δηλοῦσι(ν)",
          "answer": "we / you (plural) / they make clear — 1. Contract verbs in -όω"
        },
        {
          "prompt": "δηλοῦν / δηλῶν",
          "answer": "to make clear / making clear (masculine nominative singular) — 1. Contract verbs in -όω"
        },
        {
          "prompt": "ἐδήλουν / ἐδήλου",
          "answer": "I/they was/were making clear / he was making clear — 1. Contract verbs in -όω"
        },
        {
          "prompt": "ὁ νοῦς / τοῦ νοῦ",
          "answer": "mind / of the mind — 2. Contract second-declension nouns"
        },
        {
          "prompt": "τῷ νῷ / τὸν νοῦν",
          "answer": "to the mind / the mind (object) — 2. Contract second-declension nouns"
        },
        {
          "prompt": "ὁ πλοῦς / τοῦ πλοῦ",
          "answer": "voyage / of the voyage — 2. Contract second-declension nouns"
        },
        {
          "prompt": "οἱ πλοῖ / τοὺς πλοῦς",
          "answer": "voyages (subject) / voyages (object) — 2. Contract second-declension nouns"
        },
        {
          "prompt": "εἷς / μία / ἕν",
          "answer": "one: masculine / feminine / neuter — 3. Numbers and measured claims"
        },
