    "grammar-flashcards": {
      "title": "Lesson 35 Grammar Flashcards",
      "cards": [
        {
          "prompt": "τοῦ Σωκράτους λέγοντος",
          "answer": "while Socrates was speaking — 1. The genitive absolute"
        },
        {
          "prompt": "τῶν φίλων ζητούντων",
          "answer": "while the friends were investigating — 1. The genitive absolute"
        },
        {
          "prompt": "τοῦ λόγου παυσαμένου",
          "answer": "when the speech had ended — 1. The genitive absolute"
        },
        {
          "prompt": "τῶν ἐπιθυμιῶν ἀρχουσῶν",
          "answer": "when desires rule — 1. The genitive absolute"
        },
        {
          "prompt": "τοῦ φίλου λέγοντος, ὁ παῖς ἤκουεν.",
          "answer": "While the friend spoke, the boy listened. — 2. Participial aspect and shared subjects"
        },
        {
          "prompt": "τοῦ φίλου ἐλθόντος, ὁ παῖς ἔστη.",
          "answer": "When the friend had arrived, the boy stood. — 2. Participial aspect and shared subjects"
        },
        {
          "prompt": "ὁ φίλος λέγων ἔστη.",
          "answer": "The friend stood while speaking. — 2. Participial aspect and shared subjects"
        },
        {
          "prompt": "λέγοντος / ἐλθόντος",
          "answer": "present / aorist participle, genitive masculine singular — 2. Participial aspect and shared subjects"
        },
        {
          "prompt": "ἵστημι / ἵστησι / ἱστᾶσι",
          "answer": "I / he / they make stand — 3. ἵστημι: make stand or stand?"
        },
        {
          "prompt": "ἔστησα τὸν παῖδα.",
          "answer": "I made the boy stand. — 3. ἵστημι: make stand or stand?"
        },
        {
          "prompt": "ἔστην / στῆναι / στάς",
          "answer": "I stood / to stand / having stood — 3. ἵστημι: make stand or stand?"
        },
        {
          "prompt": "ἕστηκα",
          "answer": "I am standing (perfect form, resulting state) — 3. ἵστημι: make stand or stand?"
        },
        {
          "prompt": "τὸν ἄνδρα ἄρχοντα καθιστᾶσιν.",
          "answer": "They appoint the man ruler. — 4. καθίστημι and ἀφίστημι"
        },
        {
          "prompt": "κατέστησα / κατέστην",
          "answer": "I appointed / I became or was established — 4. καθίστημι and ἀφίστημι"
        },
        {
          "prompt": "ἀπέστησα / ἀπέστην",
          "answer": "I made withdraw / I withdrew — 4. καθίστημι and ἀφίστημι"
        },
        {
          "prompt": "ἀπέστη τῆς ἀρχῆς.",
          "answer": "He withdrew from office. — 4. καθίστημι and ἀφίστημι"
        }
      ]
    },
